DO $guard$ DECLARE src JSONB; BEGIN FOR src IN SELECT value FROM jsonb_array_elements('[{"id":"chapter-dit-computer-science-networking-devices","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":6,"title":"Networking Devices","description":"100 supplied English and Urdu MCQs organised into 10 source topics.","is_active":true,"book_title":"Computer Networking","display_chapter_number":3},{"id":"chapter-dit-computer-science-transmission-media","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":7,"title":"Transmission Media","description":"110 supplied English and Urdu MCQs organised into 11 source topics.","is_active":true,"book_title":"Computer Networking","display_chapter_number":4},{"id":"chapter-dit-computer-science-network-models","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":8,"title":"Network Models","description":"150 supplied English and Urdu MCQs organised into 15 source topics.","is_active":true,"book_title":"Computer Networking","display_chapter_number":5},{"id":"chapter-dit-computer-science-ip-addresses","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":9,"title":"IP Addresses","description":"70 supplied English and Urdu MCQs organised into 7 source topics.","is_active":true,"book_title":"Computer Networking","display_chapter_number":6},{"id":"chapter-dit-computer-science-protocols","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":10,"title":"Protocols","description":"100 supplied English and Urdu MCQs organised into 10 source topics.","is_active":true,"book_title":"Computer Networking","display_chapter_number":7},{"id":"chapter-dit-computer-science-excel","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":11,"title":"Microsoft Excel","description":"130 supplied English and Urdu MCQs organised into 13 source topics.","is_active":true,"book_title":"MS Office","display_chapter_number":3},{"id":"chapter-dit-computer-science-access","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":12,"title":"Microsoft Access","description":"100 supplied English and Urdu MCQs organised into 10 source topics.","is_active":true,"book_title":"MS Office","display_chapter_number":5}]'::jsonb) LOOP IF EXISTS(SELECT 1 FROM public.chapters c WHERE c.class_slug=src->>'class_slug' AND c.subject_slug=src->>'subject_slug' AND c.chapter_number=(src->>'chapter_number')::INT AND c.id<>src->>'id') THEN RAISE EXCEPTION 'Chapter storage collision'; END IF; END LOOP; END $guard$;
INSERT INTO public.chapters("id","class_slug","subject_slug","chapter_number","title","description","is_active","book_title","display_chapter_number") SELECT "id","class_slug","subject_slug","chapter_number","title","description","is_active","book_title","display_chapter_number" FROM jsonb_populate_recordset(NULL::public.chapters,'[{"id":"chapter-dit-computer-science-networking-devices","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":6,"title":"Networking Devices","description":"100 supplied English and Urdu MCQs organised into 10 source topics.","is_active":true,"book_title":"Computer Networking","display_chapter_number":3},{"id":"chapter-dit-computer-science-transmission-media","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":7,"title":"Transmission Media","description":"110 supplied English and Urdu MCQs organised into 11 source topics.","is_active":true,"book_title":"Computer Networking","display_chapter_number":4},{"id":"chapter-dit-computer-science-network-models","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":8,"title":"Network Models","description":"150 supplied English and Urdu MCQs organised into 15 source topics.","is_active":true,"book_title":"Computer Networking","display_chapter_number":5},{"id":"chapter-dit-computer-science-ip-addresses","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":9,"title":"IP Addresses","description":"70 supplied English and Urdu MCQs organised into 7 source topics.","is_active":true,"book_title":"Computer Networking","display_chapter_number":6},{"id":"chapter-dit-computer-science-protocols","class_slug":"dit-intermediate","subject_slug":"dit-computer-science","chapter_number":10,"title":"Protocols","description":"100 supplied English and Urdu MCQs organised into 10 source topics.","is_active":true,"book_title":"Computer Networking","display_chapter_number":7},{"id":"chapter-